-- secure_uart_crypto_top_tb.vhd  End-to-end test over the serial pins.
-- Drives request frames on uart_rx_pin at the UART bit rate, decodes the response frame from
-- uart_tx_pin by mid-bit sampling, and compares byte-for-byte with frames generated by an
-- independent model (scripts/gen_e2e_vectors.py -> tests/protocol_cases/e2e_cases.txt).
-- Generic BAUD_G defaults to 115200 to keep simulation short; run with -gBAUD_G=9600 for the
-- specified rate (scripts/run_simulation.sh does both).
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use std.textio.all;
use std.env.all;

entity secure_uart_crypto_top_tb is
    generic (BAUD_G : positive := 115200);
end entity;

architecture sim of secure_uart_crypto_top_tb is
    constant CLK_PERIOD : time := 20 ns;
    constant T_BIT      : time := 1 sec / BAUD_G;

    signal clk, rst_in : std_logic := '0';
    signal rx_pin : std_logic := '1';
    signal tx_pin : std_logic;
    signal zeroize, key_load : std_logic := '0';
    signal key_in : std_logic_vector(127 downto 0) := (others => '0');
    signal ctr_valid : std_logic := '1';
    signal ctr_store_req, ctr_store_ack : std_logic;
    signal ctr_store_val : std_logic_vector(63 downto 0);
    signal last_store : std_logic_vector(63 downto 0) := (others => '0');
    signal ctr_nv     : std_logic_vector(63 downto 0) := x"0000000000001000";  -- durable counter value
    signal seq_req, seq_ack, seq_have : std_logic;
    signal seq_val    : std_logic_vector(15 downto 0);
    signal seq_nv     : std_logic_vector(15 downto 0) := (others => '0');
    signal seq_nv_have : std_logic := '0';
    signal busy, st_ferr, st_ovf, st_perr, st_auth, st_replay : std_logic;
    signal n_perr, n_auth, n_replay, n_ferr, n_ovf : natural := 0;

    subtype byte_t is std_logic_vector(7 downto 0);
    type bytes_t is array (0 to 1023) of byte_t;
    type queue_t is array (0 to 4095) of byte_t;
    signal q    : queue_t;
    signal q_wr : natural := 0;
begin
    clk <= not clk after CLK_PERIOD / 2;

    dut : entity work.secure_uart_crypto_top
        generic map (BAUD_RATE => BAUD_G, PARSER_TIMEOUT_CLKS => 150_000)
        port map (clk => clk, rst_in => rst_in, uart_rx_pin => rx_pin, uart_tx_pin => tx_pin,
                  zeroize => zeroize, key_load => key_load, key_in => key_in,
                  ctr_init => ctr_nv, ctr_valid => ctr_valid,
                  seq_init => seq_nv, seq_have_init => seq_nv_have, seq_valid => '1',
                  seq_store_req => seq_req, seq_store_val => seq_val, seq_store_ack => seq_ack,
                  ctr_store_req => ctr_store_req, ctr_store_val => ctr_store_val,
                  ctr_store_ack => ctr_store_ack, busy => busy, st_framing_err => st_ferr,
                  st_rx_overflow => st_ovf, st_parse_err => st_perr, st_auth_fail => st_auth,
                  st_replay => st_replay);

    -- non-volatile counter store model: acknowledges after a few clocks and records the value
    nv : process
    begin
        ctr_store_ack <= '0';
        loop
            wait until rising_edge(clk) and ctr_store_req = '1';
            last_store <= ctr_store_val;
            for i in 1 to 6 loop wait until rising_edge(clk); end loop;
            ctr_store_ack <= '1';
            ctr_nv <= last_store;                    -- durable once acknowledged
            wait until rising_edge(clk);
            ctr_store_ack <= '0';
            wait until ctr_store_req = '0';
        end loop;
    end process;

    nv_seq : process
    begin
        seq_ack <= '0';
        loop
            wait until rising_edge(clk) and seq_req = '1';
            for i in 1 to 6 loop wait until rising_edge(clk); end loop;
            seq_ack <= '1';
            seq_nv <= seq_val; seq_nv_have <= '1';  -- durable once acknowledged
            wait until rising_edge(clk);
            seq_ack <= '0';
            wait until seq_req = '0';
        end loop;
    end process;

    events : process (clk)
    begin
        if rising_edge(clk) then
            if st_perr = '1' then n_perr <= n_perr + 1; end if;
            if st_auth = '1' then n_auth <= n_auth + 1; end if;
            if st_replay = '1' then n_replay <= n_replay + 1; end if;
            if st_ferr = '1' then n_ferr <= n_ferr + 1; end if;
            if st_ovf = '1' then n_ovf <= n_ovf + 1; end if;
        end if;
    end process;

    -- continuous serial decoder for the DUT's TX pin (independent of the stimulus timing)
    tx_mon : process
        variable d : byte_t;
        variable n : natural := 0;
    begin
        loop
            wait until tx_pin = '0';
            wait for T_BIT / 2;
            assert tx_pin = '0' report "TX start bit glitch" severity failure;
            for i in 0 to 7 loop
                wait for T_BIT; d(i) := tx_pin;
            end loop;
            wait for T_BIT;
            assert tx_pin = '1' report "TX stop bit not high" severity failure;
            q(n mod 4096) <= d;
            n := n + 1;
            q_wr <= n;
        end loop;
    end process;

    stim : process
        file f : text open read_mode is "tests/protocol_cases/e2e_cases.txt";
        variable l : line;
        variable lineno : natural := 0;
        variable req, exp, got : bytes_t;
        variable nreq, nexp : natural;
        variable p, s, e : natural;
        variable ncase : natural := 0;
        variable v64 : std_logic_vector(63 downto 0);
        variable ev_a, ev_r, ev_p : integer;

        function hex_val (c : character) return natural is
        begin
            case c is
                when '0' to '9' => return character'pos(c) - character'pos('0');
                when 'a' to 'f' => return character'pos(c) - character'pos('a') + 10;
                when 'A' to 'F' => return character'pos(c) - character'pos('A') + 10;
                when others => report "bad hex" severity failure; return 0;
            end case;
        end function;

        procedure parse_hex (str : string; buf : out bytes_t; n : out natural) is
        begin
            buf := (others => (others => '0'));
            n := str'length / 2;
            for i in 0 to n - 1 loop
                buf(i) := std_logic_vector(to_unsigned(hex_val(str(str'left + 2 * i)) * 16 +
                                                       hex_val(str(str'left + 2 * i + 1)), 8));
            end loop;
        end procedure;

        procedure get_tok (ln : string; pos : inout natural; st : out natural; en : out natural) is
        begin
            while pos <= ln'right and ln(pos) = ' ' loop pos := pos + 1; end loop;
            st := pos;
            while pos <= ln'right and ln(pos) /= ' ' loop pos := pos + 1; end loop;
            en := pos - 1;
        end procedure;

        procedure send_byte (b : byte_t) is
        begin
            rx_pin <= '0'; wait for T_BIT;
            for i in 0 to 7 loop rx_pin <= b(i); wait for T_BIT; end loop;
            rx_pin <= '1'; wait for T_BIT;
        end procedure;

        variable q_rd : natural := 0;

        procedure recv_byte (b : out byte_t; first_timeout : time) is
        begin
            if q_wr = q_rd then
                wait until q_wr /= q_rd for first_timeout;
            end if;
            assert q_wr /= q_rd report "line " & integer'image(lineno) & ": response byte missing (timeout)"
                severity failure;
            b := q(q_rd mod 4096);
            q_rd := q_rd + 1;
        end procedure;
    begin
        rst_in <= '1'; wait for 10 * CLK_PERIOD; rst_in <= '0';
        wait for 100 * CLK_PERIOD;

        while not endfile(f) loop
            readline(f, l);
            next when l'length = 0;
            lineno := lineno + 1;
            p := l'left;
            get_tok(l.all, p, s, e);

            if l.all(s to e) = "REQ" then
                get_tok(l.all, p, s, e); parse_hex(l.all(s to e), req, nreq);
                get_tok(l.all, p, s, e); parse_hex(l.all(s to e), exp, nexp);
                for i in 0 to nreq - 1 loop send_byte(req(i)); end loop;
                -- the first response byte may be delayed by processing or the parser timeout
                for i in 0 to nexp - 1 loop
                    recv_byte(got(i), 200 ms);
                    if got(i) /= exp(i) then
                        report "line " & integer'image(lineno) & ": response byte " & integer'image(i) &
                               " expected " & to_hstring(exp(i)) & " got " & to_hstring(got(i))
                            severity failure;
                    end if;
                end loop;
                -- nothing else may follow (no extra frame, no leaked plaintext)
                wait for 40 * T_BIT;
                assert tx_pin = '1' and q_wr = q_rd
                    report "line " & integer'image(lineno) & ": unexpected extra output" severity failure;
                ncase := ncase + 1;

            elsif l.all(s to e) = "CTRVALID" then
                get_tok(l.all, p, s, e);
                if l.all(s) = '1' then ctr_valid <= '1'; else ctr_valid <= '0'; end if;
                wait for 10 * CLK_PERIOD;

            elsif l.all(s to e) = "REQ_RESET" then
                get_tok(l.all, p, s, e); parse_hex(l.all(s to e), req, nreq);
                for i in 0 to nreq - 2 loop send_byte(req(i)); end loop;
                -- last byte: start + data bits, then idle level; reset is triggered by the controller
                -- going busy (baud-rate independent), 150 clocks into the AES-GCM transaction
                rx_pin <= '0'; wait for T_BIT;
                for i in 0 to 7 loop rx_pin <= req(nreq - 1)(i); wait for T_BIT; end loop;
                rx_pin <= '1';
                wait until busy = '1' for 4 * T_BIT;
                wait for 150 * CLK_PERIOD;                 -- engine is mid-transaction here
                assert busy = '1' report "line " & integer'image(lineno) & ": expected device busy before reset"
                    severity failure;
                rst_in <= '1'; wait for 6 * CLK_PERIOD; rst_in <= '0';
                wait for 300 * T_BIT;                      -- also lets the stop bit finish
                assert tx_pin = '1' and q_wr = q_rd and busy = '0'
                    report "line " & integer'image(lineno) & ": output after mid-transaction reset" severity failure;

            elsif l.all(s to e) = "RESET" then
                rst_in <= '1'; wait for 6 * CLK_PERIOD; rst_in <= '0';
                wait for 100 * CLK_PERIOD;

            elsif l.all(s to e) = "LOADKEY" then
                get_tok(l.all, p, s, e); parse_hex(l.all(s to e), req, nreq);
                for i in 0 to 15 loop key_in(127 - 8 * i downto 120 - 8 * i) <= req(i); end loop;
                wait for 2 * CLK_PERIOD;
                key_load <= '1'; wait for CLK_PERIOD; key_load <= '0';
                wait for 10 * CLK_PERIOD;

            elsif l.all(s to e) = "EXPECT_EVENTS" then
                get_tok(l.all, p, s, e); ev_a := integer'value(l.all(s to e));
                get_tok(l.all, p, s, e); ev_r := integer'value(l.all(s to e));
                get_tok(l.all, p, s, e); ev_p := integer'value(l.all(s to e));
                assert n_auth = ev_a   report "auth-fail events: " & integer'image(n_auth) severity failure;
                assert n_replay = ev_r report "replay events: " & integer'image(n_replay) severity failure;
                assert n_perr = ev_p   report "parse-error events: " & integer'image(n_perr) severity failure;

            elsif l.all(s to e) = "ZEROIZE" then
                zeroize <= '1'; wait for 3 * CLK_PERIOD; zeroize <= '0';
                wait for 10 * CLK_PERIOD;

            elsif l.all(s to e) = "EXPECT_STORE" then
                get_tok(l.all, p, s, e);
                parse_hex(l.all(s to e), req, nreq);
                for i in 0 to 7 loop v64(63 - 8 * i downto 56 - 8 * i) := req(i); end loop;
                assert last_store = v64
                    report "line " & integer'image(lineno) & ": NV counter store mismatch, got " &
                           to_hstring(last_store) severity failure;
            else
                report "unknown directive at line " & integer'image(lineno) severity failure;
            end if;
        end loop;

        assert n_ferr = 0 and n_ovf = 0 report "UART framing/overflow events" severity failure;

        report "secure_uart_crypto_top_tb (BAUD=" & integer'image(BAUD_G) & "): " &
               integer'image(ncase) & " wire-level cases PASSED";
        report "secure_uart_crypto_top_tb: ALL TESTS PASSED";
        finish;
    end process;

    watchdog : process
    begin
        wait for 60 sec;
        report "secure_uart_crypto_top_tb: TIMEOUT" severity failure;
    end process;
end architecture;
